package glitch

import data.glitch_lib

# Set of deprecated cryptographic algorithms and hash functions to detect
deprecated_crypto := {"sha1", "md5", "md4", "des", "3des", "rc4", "blowfish", "rsa-1024"}

# Check if a string value contains any deprecated crypto keyword
check_deprecated_crypto_string(value) {
    value.ir_type == "String"
    some crypto in deprecated_crypto
    regex.match(sprintf("(?i).*%s.*", [crypto]), value.value)
}

# Check if a function call uses a deprecated hash function
check_deprecated_function_call(func) {
    func.ir_type == "FunctionCall"
    some crypto in deprecated_crypto
    regex.match(sprintf("(?i).*%s.*", [crypto]), func.name)
}

# Check if an attribute value uses deprecated crypto
check_deprecated_attribute(attr) {
    check_deprecated_crypto_string(attr.value)
} else {
    check_deprecated_function_call(attr.value)
}

# Main rule for detecting deprecated cryptographic algorithms
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check if the attribute uses deprecated crypto
    check_deprecated_attribute(attr)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of deprecated cryptographic algorithm - Avoid using deprecated cryptographic algorithms. (CWE-327)"
    }
}

# Also check variables (for Chef and other IaC)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all variables in the parent
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if the variable uses deprecated crypto
    check_deprecated_attribute(var)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of deprecated cryptographic algorithm - Avoid using deprecated cryptographic algorithms. (CWE-327)"
    }
}

