    # Check all attributes, variables, and atomic units in the parent
    all_attrs := glitch_lib.all_attributes(parent)
    all_vars := glitch_lib.all_variables(parent)
    all_units := glitch_lib.all_atomic_units(parent)

    # Combine all elements to check
    all_elements := array.concat(array.concat(all_attrs, all_vars), all_units)
