package glitch

import data.glitch_lib

# Define deprecated algorithms and protocols as sets
deprecated_algorithms := {"DES", "3DES", "RC4", "SHA-1", "MD5", "AES-ECB", "Blowfish", "RSA-1024"}
deprecated_protocols := {"SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "SSHv1"}

# Helper to check if a string contains any deprecated algorithm
contains_deprecated_algorithm(str) {
    contains_algorithm := contains(lower(str), "des")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "3des")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "rc4")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "sha-1")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "md5")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "aes-ecb")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "blowfish")
    contains_algorithm
} else {
    contains_algorithm := contains(lower(str), "rsa-1024")
    contains_algorithm
}

# Helper to check if a string contains any deprecated protocol
contains_deprecated_protocol(str) {
    contains_protocol := contains(lower(str), "sslv2")
    contains_protocol
} else {
    contains_protocol := contains(lower(str), "sslv3")
    contains_protocol
} else {
    contains_protocol := contains(lower(str), "tls 1.0")
    contains_protocol
} else {
    contains_protocol := contains(lower(str), "tls 1.1")
    contains_protocol
} else {
    contains_protocol := contains(lower(str), "sshv1")
    contains_protocol
}

# Main rule for deprecated algorithms in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.value.ir_type == "String"
    lower_value := lower(attr.value.value)
    contains_deprecated_algorithm(lower_value)
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or deprecated cryptographic algorithm (CWE-327)"
    }
}

# Main rule for deprecated protocols in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.value.ir_type == "String"
    lower_value := lower(attr.value.value)
    contains_deprecated_protocol(lower_value)
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or deprecated cryptographic protocol (CWE-327)"
    }
}
